Lemma sx32_m1 : sx32 (Z_to_bv 64 4294967295) = Z_to_bv 64 18446744073709551615.
Proof. apply bv_eq. vm_compute. reflexivity. Qed.

Definition GET_VALUE_STACK : Z := 48 + SNPRINTF_STACK.

Definition get_value_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (k : cfgkey) (buf lo : Z) (junk : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (gv_res k buf)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (buf, buf + 22)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' buf (gv_buf k junk)
    /\ CanaryReads m'.

Definition get_value_stmt (k : cfgkey) : Prop :=
  forall (c buf lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (junk : list byte),
  F = bvmap_empty -> fc = Z_to_bv 32 0 ->
  ro_cells usegs m (c + O_CFG_HINT) [C4 (wz 4294967295)] ->
  (c + O_CFG_HINT + 4 <= lo \/ bv_unsigned sp <= c + O_CFG_HINT) ->
  rw_cells usegs m buf [CB 22 junk] ->
  bv_unsigned sp <= buf -> buf + 22 <= 0x7fffffffffff -> buf mod 16 = 2 ->
  bv_unsigned sp mod 16 = 0 ->
  stk usegs m lo (bv_unsigned sp) -> lo + GET_VALUE_STACK <= bv_unsigned sp -> hceil <= lo ->
  CanaryReads m ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (get_value_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc k buf lo junk m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz c) (wz L_STR_SCHEDULER) (wz (key_lit k)) (wz buf) (wz 22) a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_CONFIG_GET_VALUE) fc None m (seg_rom usegs)).


