Local Ltac gv_prologue :=
  unfold get_value_stmt;
  intros c buf lo ra sp gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m junk;
  intros FZ FCZ HINT HSEP BUF SPB BHI B16 SP16 ST LO HC CAN RA MI;
  unfold GET_VALUE_STACK, SNPRINTF_STACK in LO; unfold O_CFG_HINT in *;
  hcb; sp_range sp;
  pose proof (rw_cells_bound _ _ _ _ BUF) as BB; cbn [cells_size csize Nat.add length] in BB;
  init_fp [(lo, bv_unsigned sp); (buf, buf + 22)]%Z;
  unfold P_CONFIG_GET_VALUE, wz in *; cbn [key_lit gv_res gv_buf] in *;
  unfold L_STR_SCHEDULER, L_STR_CONCURRENCY_HINT, L_STR_ASSUME_CONT, L_STR_LOCKING, L_STR_SPIN,
         L_STR_TASK_USEC, L_STR_WAIT_USEC, L_STR_ONE in *;
  carve_frame 48%nat ST;
  (* [comment removed for export] *)
  do 12 step;
  (* [comment removed for export] *)
  do 4 step;
  let SC := fresh "SC" in
  pose proof strcmp_SCHED_SCHED as SC; unfold strcmp_lit_stmt, L_STR_SCHEDULER, wz in SC;
  call SC; [fast_assumption|]; clear SC;
  step; if_true.

(* [comment removed for export] *)
Local Ltac gv_cmp LEM :=
  do 4 step;
  let SC := fresh "SC" in
  pose proof LEM as SC;
  unfold strcmp_lit_stmt, L_STR_CONCURRENCY_HINT, L_STR_ASSUME_CONT, L_STR_LOCKING, L_STR_SPIN,
         L_STR_TASK_USEC, L_STR_WAIT_USEC, wz in SC;
  call SC; [fast_assumption|]; clear SC.

(* [comment removed for export] *)
Local Ltac gv_epilogue CAN MU sp :=
  do 9 step;
  match goal with ST' : stk _ _ _ _, FR' : rw_cells _ _ (bv_unsigned sp + -48) _ |- _ =>
    release_frame FR' ST' (bv_unsigned sp) end;
  finish;
  eapply CanaryReads_transport; [exact CAN | exact MU | |]; unfold G_GOT_STACK_CHK, G_STACK_CHK_GUARD; cbn; lia.

(* [comment removed for export] *)
Local Ltac gv_default L1 L2 CAN MU sp :=
  gv_prologue; gv_cmp L1; step; if_false; gv_cmp L2; step; if_false; step; gv_epilogue CAN MU sp.
